const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const donnerPass = ee.Geometry.Point([-120.3259, 39.3166]);
  const startDate = '2022-01-01';
  const endDate = '2022-04-30';

  // 2. Data Acquisition - MODIS Snow Water Equivalent
  const collection = ee.ImageCollection('MODIS/061/MOD10C1')
    .filterDate(startDate, endDate)
    .filterBounds(donnerPass);

  const collectionSize = collection.size().getInfo();
  console.log(`2022 Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Convert SWE from mm to inches
  const sweInInches = collection.map(function(image) {
    return image.select('Snow_Water_Equivalent')
      .multiply(0.0393701); // Convert mm to inches
  });

  // Calculate maximum SWE during the period
  const maxSWE = sweInInches.max();

  // 4. Calculate statistics
  const stats = maxSWE.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: donnerPass,
    scale: 5000,
    maxPixels: 1e9
  });

  const sweValue = stats.get('Snow_Water_Equivalent').getInfo();
  const pixelCount = maxSWE.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: donnerPass,
    scale: 5000,
    maxPixels: 1e9
  }).get('Snow_Water_Equivalent').getInfo();

  console.log(`Max SWE (inches): ${sweValue ? sweValue.toFixed(2) : 'No data'}`);
  console.log(`Valid pixels: ${pixelCount}`);

  // 5. Validation & Final Answer
  if (sweValue === null || sweValue === undefined || isNaN(sweValue)) {
    console.log("<answer>C3</answer>");
  } else if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (sweValue > 40) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
